import{_ as a,c as i,o as s,a2 as r}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/troubleshooting.md","filePath":"fr/guide/troubleshooting.md","lastUpdated":1793163976000}'),l={name:"fr/guide/troubleshooting.md"};function o(n,e,t,p,u,c){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h1><p>Cette page recense les problèmes courants de NueZip sur macOS et leur résolution.</p><h2 id="l-application-ne-demarre-pas-ou-plante-au-lancement" tabindex="-1">L&#39;application ne démarre pas ou plante au lancement <a class="header-anchor" href="#l-application-ne-demarre-pas-ou-plante-au-lancement" aria-label="Permalink to &quot;L&#39;application ne démarre pas ou plante au lancement&quot;">​</a></h2><p>Symptômes : NueZip ne s&#39;ouvre pas, plante immédiatement ou affiche une erreur inattendue.</p><p>Étapes à essayer :</p><ol><li>Assurez-vous que votre version de macOS répond aux exigences minimales (macOS 14 Sonoma+).</li><li>Quittez et relancez l&#39;application.</li><li>Redémarrez votre Mac.</li><li>Si l&#39;application a été téléchargée depuis GitHub Releases, essayez de télécharger la dernière version ou la version notariée.</li><li>Si les problèmes persistent, collectez les journaux (voir ci-dessous) et ouvrez un problème.</li></ol><h2 id="impossible-d-ouvrir-une-archive-rar" tabindex="-1">Impossible d&#39;ouvrir une archive RAR <a class="header-anchor" href="#impossible-d-ouvrir-une-archive-rar" aria-label="Permalink to &quot;Impossible d&#39;ouvrir une archive RAR&quot;">​</a></h2><p>Symptômes : NueZip échoue à ouvrir un fichier <code>.rar</code>, ou affiche une erreur.</p><p>Liste de contrôle :</p><ol><li>Assurez-vous que le fichier RAR n&#39;est pas corrompu. Essayez de l&#39;ouvrir avec un autre outil comme The Unarchiver.</li><li>Les archives RAR multi-volumes doivent avoir toutes les parties présentes (<code>.part1.rar</code>, <code>.part2.rar</code>, etc.).</li><li>Les archives RAR protégées par mot de passe nécessitent le mot de passe correct.</li><li>Le format RAR5 est pris en charge. Si vous avez un format RAR plus ancien, veuillez le signaler.</li></ol><h2 id="l-extraction-echoue-avec-une-erreur-de-mot-de-passe" tabindex="-1">L&#39;extraction échoue avec une erreur de mot de passe <a class="header-anchor" href="#l-extraction-echoue-avec-une-erreur-de-mot-de-passe" aria-label="Permalink to &quot;L&#39;extraction échoue avec une erreur de mot de passe&quot;">​</a></h2><p>Symptômes : L&#39;extraction échoue avec « Mauvais mot de passe » ou une erreur de déchiffrement.</p><p>Liste de contrôle :</p><ol><li>Vérifiez que le mot de passe est correct — les mots de passe sont sensibles à la casse.</li><li>Assurez-vous que le bon type de chiffrement est pris en charge (AES-256 pour ZIP).</li><li>Essayez de saisir à nouveau le mot de passe depuis le gestionnaire de mots de passe.</li></ol><h2 id="l-extension-finder-n-apparait-pas" tabindex="-1">L&#39;extension Finder n&#39;apparaît pas <a class="header-anchor" href="#l-extension-finder-n-apparait-pas" aria-label="Permalink to &quot;L&#39;extension Finder n&#39;apparaît pas&quot;">​</a></h2><p>Symptômes : Le clic droit sur une archive dans Finder n&#39;affiche aucune option NueZip.</p><p>Liste de contrôle :</p><ol><li>Activez l&#39;extension : Réglages système → Confidentialité et sécurité → Extensions → Extensions Finder → Activer <strong>NueZip</strong>.</li><li>Redémarrez Finder : Clic droit sur Finder dans Moniteur d&#39;activité → Relancer, ou exécutez <code>killall Finder</code> dans le Terminal.</li><li>Réinstallez l&#39;application si l&#39;extension n&#39;apparaît toujours pas.</li></ol><h2 id="licence-achat-non-affiche" tabindex="-1">Licence / achat non affiché <a class="header-anchor" href="#licence-achat-non-affiche" aria-label="Permalink to &quot;Licence / achat non affiché&quot;">​</a></h2><p>Symptômes : Vous avez acheté NueZip mais il apparaît toujours comme version d&#39;essai.</p><p>Liste de contrôle :</p><ol><li>Assurez-vous d&#39;être connecté avec le même identifiant Apple utilisé pour l&#39;achat.</li><li>Restaurez les achats : NueZip → Réglages → Licence → Restaurer les achats.</li><li>Contactez le support si le problème persiste.</li></ol><h2 id="comment-collecter-les-journaux-de-debogage" tabindex="-1">Comment collecter les journaux de débogage <a class="header-anchor" href="#comment-collecter-les-journaux-de-debogage" aria-label="Permalink to &quot;Comment collecter les journaux de débogage&quot;">​</a></h2><p>Pour aider à diagnostiquer les problèmes, collectez les journaux de débogage depuis NueZip :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copier les journaux sur le Bureau pour les partager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>Ouvrez ensuite un problème sur <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> et joignez les journaux.</p><h2 id="problemes-lies-aux-permissions" tabindex="-1">Problèmes liés aux permissions <a class="header-anchor" href="#problemes-lies-aux-permissions" aria-label="Permalink to &quot;Problèmes liés aux permissions&quot;">​</a></h2><p>Si une fonctionnalité demande une permission mais ne fonctionne pas après l&#39;avoir accordée :</p><ol><li>Quittez l&#39;application et rouvrez-la après avoir accordé la permission.</li><li>Si nécessaire, réinitialisez l&#39;invite de permission avec <code>tccutil</code> (voir le <a href="./permissions.html">guide des permissions</a>).</li></ol><h2 id="problemes-de-performance" tabindex="-1">Problèmes de performance <a class="header-anchor" href="#problemes-de-performance" aria-label="Permalink to &quot;Problèmes de performance&quot;">​</a></h2><p>Si l&#39;application est lente ou ne répond pas :</p><ol><li>Fermez les autres applications gourmandes.</li><li>Essayez d&#39;extraire une archive plus petite pour isoler le problème.</li><li>Redémarrez l&#39;application si les performances se dégradent avec le temps.</li></ol><h2 id="consulter-les-journaux" tabindex="-1">Consulter les journaux <a class="header-anchor" href="#consulter-les-journaux" aria-label="Permalink to &quot;Consulter les journaux&quot;">​</a></h2><p>Pour résoudre les plantages ou problèmes, les journaux de l&#39;application sont l&#39;artefact le plus utile. Dans les versions sandbox (App Store), vérifiez :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="reinitialiser-l-application" tabindex="-1">Réinitialiser l&#39;application <a class="header-anchor" href="#reinitialiser-l-application" aria-label="Permalink to &quot;Réinitialiser l&#39;application&quot;">​</a></h2><p>Pour réinitialiser les réglages et effacer les données locales :</p><ol><li>Quittez NueZip</li><li>Supprimez le conteneur (soyez prudent — cela supprime tous les réglages) :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>Rouvrez NueZip et reconfigurez.</li></ol><h2 id="signaler-un-probleme" tabindex="-1">Signaler un problème <a class="header-anchor" href="#signaler-un-probleme" aria-label="Permalink to &quot;Signaler un problème&quot;">​</a></h2><p>Lors de l&#39;ouverture d&#39;un problème, incluez :</p><ul><li>Version de macOS (menu Pomme → À propos de ce Mac)</li><li>Version de NueZip (NueZip → À propos)</li><li>Étapes pour reproduire</li><li>Journaux (voir la section <a href="#view-logs">Consulter les journaux</a> pour savoir comment les collecter)</li></ul><p>Cela aide les mainteneurs à identifier et corriger le problème plus rapidement.</p>`,44)])])}const m=a(l,[["render",o]]);export{h as __pageData,m as default};
